1	export class QuotaExceededError extends Error {
2	  constructor(code, message) {
3	    super(message);
4	    this.name = 'QuotaExceededError';
5	    this.code = code;
6	  }
7	}
8	
9	// Internal state of every gate, shared with child gates through a WeakMap so
10	// the public gate object keeps its exact shape.
11	const gateState = new WeakMap();
12	
13	// Monotonic counter that never repeats or moves backwards, independent of the
14	// (mocked, possibly frozen) wall clock; gives queued entries a global arrival
15	// order so reparented queues can merge fairly.
16	let enqueueSeq = 0;
17	
18	// setTimeout/setInterval clamp delays beyond the signed 32-bit range to 1ms,
19	// which would expire a patient waiter — or flip a long window — almost
20	// immediately. Long delays therefore fire in real-time chunks: each fire
21	// consumes one chunk and re-arms the remainder, so the measured wait is real
22	// elapsed time exactly like a single timer.
23	const MAX_TIMER_DELAY = 0x7fffffff;
24	
25	function assertInteger(value, name) {
26	  if (typeof value !== 'number' || !Number.isInteger(value)) {
27	    throw new TypeError(`${name} must be an integer`);
28	  }
29	}
30	
31	function assertSignal(signal) {
32	  if (
33	    signal !== undefined &&
34	    signal !== null &&
35	    (typeof signal !== 'object' ||
36	      typeof signal.addEventListener !== 'function' ||
37	      typeof signal.removeEventListener !== 'function')
38	  ) {
39	    throw new TypeError('signal must be an AbortSignal');
40	  }
41	}
42	
43	export function createGate({ limit, windowMs, maxWaitMs = 0, parent } = {}) {
44	  assertInteger(limit, 'limit');
45	  assertInteger(windowMs, 'windowMs');
46	  assertInteger(maxWaitMs, 'maxWaitMs');
47	  if (limit <= 0) throw new RangeError('limit must be a positive integer');
48	  if (windowMs <= 0) throw new RangeError('windowMs must be a positive integer');
49	  if (maxWaitMs < 0) throw new RangeError('maxWaitMs must not be negative');
50	
51	  let parentState = null;
52	  if (parent !== undefined && parent !== null) {
53	    parentState = gateState.get(parent);
54	    if (parentState === undefined) {
55	      throw new TypeError('parent must be a gate created by createGate');
56	    }
57	    if (limit > parentState.limit) {
58	      throw new RangeError('limit must not exceed parent limit');
59	    }
60	  }
61	
62	  const state = {
63	    limit,
64	    windowMs,
65	    maxWaitMs,
66	    parent: parentState,
67	    children: new Set(),
68	    isRoot: parentState === null,
69	    // Own-window accounting.
70	    ownGen: 0, // bumped on every own-window flip, invalidates old handles
71	    usedOwn: 0, // own units occupied or lent out in the current own window
72	    inFlight: 0, // units occupied through this gate and not yet cleared
73	    borrowedInFlight: 0, // units this gate's occupations borrowed, still live
74	    lentInFlight: 0, // own units lent to descendants' admitted occupations
75	    poolDraw: 0, // committed pool charge, valid only when drawGen === poolGen
76	    drawGen: -1,
77	    // Cross-gate reservation accounting. A pending acquireAll first reserves
78	    // the member's own current-window slice, then own slices up the direct
79	    // parent chain (each step registering the lend); the root pool covers the
80	    // remainder. Every gathered unit draws pool room until commit or rollback.
81	    //
82	    // A non-root gate's reserved units are pendingOwn + pendingLends: own
83	    // window units promised to pending combos, as member or as ancestor
84	    // lender. The root's reserved units are poolResvUnits: uncommitted units
85	    // drawn from the pool. Across the family every reserved unit counts once.
86	    rolledBack: 0, // failed whole-combo reservation attempts owned here
87	    pendingOwn: 0,
88	    pendingLends: 0,
89	    resvAsMember: new Set(), // entries holding pendingOwn here
90	    resvAsLender: new Set(), // entries holding pendingLends here
91	    lentLinks: new Set(), // admitted occupation links lent from this gate
92	    // Observability.
93	    waiting: 0, // units currently queued through this gate
94	    granted: 0,
95	    refused: 0,
96	    expired: 0,
97	    cancelled: 0,
98	    openHandles: new Set(),
99	    root: null,
100	    timer: null,
101	  };
102	
103	  let root;
104	  if (parentState === null) {
105	    root = state;
106	    // The quota pool shared by the whole hierarchy lives on the root gate.
107	    Object.assign(state, {
108	      poolLimit: limit,
109	      poolGen: 0, // bumped on every root-window flip
110	      poolUsed: 0, // units committed or reserved in the current pool window
111	      poolLinks: new Set(), // admitted pool borrows, reclaimed at the pool flip
112	      poolResv: new Set(), // uncommitted pool reservation links
113	      poolResvUnits: 0, // sum of units behind poolResv
114	      queue: [], // queued requests from every gate, in arrival order
115	      head: 0, // index of the first live entry; entries are never shifted
116	      liveQueued: 0, // entries not yet settled
117	      serveWave: 0, // monotonic count of serves that overtook a blocked combo
118	      minDeadline: Infinity, // earliest live deadline, skips idle sweeps
119	      lastNow: 0, // monotonic clock: never moves backwards
120	      members: new Set(),
121	    });
122	    state.members.add(state);
123	  } else {
124	    root = parentState.root;
125	    root.members.add(state);
126	    parentState.children.add(state);
127	  }
128	  state.root = root;
129	
130	  // Operational helpers read state.root dynamically rather than capturing the
131	  // local `root`: reparent() can move this gate (and its descendants) into
132	  // another family's pool.
133	  function now() {
134	    const r = state.root;
135	    const t = Date.now();
136	    if (t > r.lastNow) r.lastNow = t;
137	    return r.lastNow;
138	  }
139	
140	  function effectiveDraw(node) {
141	    return node.drawGen === node.root.poolGen ? node.poolDraw : 0;
142	  }
143	
144	  function chargeDraw(node, units) {
145	    if (node.drawGen !== node.root.poolGen) {
146	      node.drawGen = node.root.poolGen;
147	      node.poolDraw = 0;
148	    }
149	    node.poolDraw += units;
150	  }
151	
152	  function reservedOn(g) {
153	    return g === g.root ? g.root.poolResvUnits : g.pendingOwn + g.pendingLends;
154	  }
155	
156	  // --- Combo reservations ---------------------------------------------------
157	  //
158	  // seg:  { gate, units, own, ownReleased, links, gen }
159	  // link: { kind:'own'|'pool', lender, units, released, gen }
160	  //
161	  // Gather plans first and applies second, so a plan the pool cannot cover is
162	  // rejected without any mutation and the whole-combo rollback is trivial.
163	  // Sibling members share ancestor chains; the tentative `claimed` map debits
164	  // ancestor headroom cumulatively inside one plan. Every registration is
165	  // intrusive: commit, rollback and window-flip reclaims touch only the gates
166	  // involved, never the queue or the whole family.
167	
168	  function buildSegs(comboGates, unitsOf) {
169	    return comboGates.map((g) => ({
170	      gate: g,
171	      units: unitsOf(g),
172	      own: 0,
173	      ownReleased: false, // member own slice already reclaimed by an own flip
174	      links: [],
175	      gen: -1,
176	    }));
177	  }
178	
179	  function ownHeadroom(g, claimed) {
180	    return Math.max(0, g.limit - g.usedOwn - g.pendingOwn - g.pendingLends - (claimed.get(g) ?? 0));
181	  }
182	
183	  // Pure plan: fills seg.own / seg.links and returns total pool need. A
184	  // member slice larger than that gate's own limit simply borrows the excess
185	  // up the chain — member limits never cap a combo, only the root pool does.
186	  function planGather(segs) {
187	    const r = state.root;
188	    const claimed = new Map();
189	    let poolNeed = 0;
190	    for (const seg of segs) {
191	      const m = seg.gate;
192	      if (m === r) {
193	        seg.links.push({ kind: 'pool', lender: r, units: seg.units, released: false, gen: -1 });
194	        poolNeed += seg.units;
195	        continue;
196	      }
197	      let need = seg.units;
198	      const own = Math.min(need, ownHeadroom(m, claimed));
199	      seg.own = own;
200	      claimed.set(m, (claimed.get(m) ?? 0) + own);
201	      need -= own;
202	      let cur = m.parent;
203	      while (need > 0 && cur !== null && cur !== r) {
204	        const lend = Math.min(need, ownHeadroom(cur, claimed));
205	        if (lend > 0) {
206	          seg.links.push({ kind: 'own', lender: cur, units: lend, released: false, gen: -1 });
207	          claimed.set(cur, (claimed.get(cur) ?? 0) + lend);
208	          need -= lend;
209	        }
210	        cur = cur.parent;
211	      }
212	      if (need > 0) {
213	        seg.links.push({ kind: 'pool', lender: r, units: need, released: false, gen: -1 });
214	        poolNeed += need;
215	      }
216	    }
217	    return poolNeed;
218	  }
219	
220	  // Apply a planned reservation; the caller pre-checked poolNeed against room.
221	  function applyGather(entry, segs) {
222	    const r = entry.owner.root;
223	    const gen = r.poolGen;
224	    for (const seg of segs) {
225	      const m = seg.gate;
226	      seg.gen = gen;
227	      seg.ownReleased = false;
228	      if (m !== r && seg.own > 0) {
229	        m.pendingOwn += seg.own;
230	        m.resvAsMember.add(entry);
231	        r.poolUsed += seg.own;
232	      }
233	      for (const link of seg.links) {
234	        link.gen = gen;
235	        r.poolUsed += link.units;
236	        if (link.kind === 'own') {
237	          link.lender.pendingLends += link.units;
238	          link.lender.resvAsLender.add(entry);
239	        } else {
240	          r.poolResv.add(link);
241	          r.poolResvUnits += link.units;
242	          if (m === r) m.resvAsMember.add(entry);
243	        }
244	      }
245	    }
246	    entry.segs = segs;
247	    entry.holdsHeld = true;
248	  }
249	
250	  // Plan, check pool room, apply — or reject without touching anything. The
251	  // whole combo draws pool room: a member's own slice and every ancestor lend
252	  // are partitions OF the pool, not capacity beyond it. Feasibility is
253	  // therefore simply poolUsed + total combo units <= poolLimit; the plan's
254	  // own/lender/pool partition only decides which own window each unit lands
255	  // on (and thus where its flip reclaims it).
256	  function tryGather(entry, segs) {
257	    const r = entry.owner.root;
258	    let total = 0;
259	    for (const seg of segs) total += seg.units;
260	    if (r.poolUsed + total > r.poolLimit) {
261	      for (const seg of segs) {
262	        seg.own = 0;
263	        seg.links = [];
264	      }
265	      return false;
266	    }
267	    planGather(segs);
268	    applyGather(entry, segs);
269	    return true;
270	  }
271	
272	  // Same whole reservation for one gate: the entry's own current-window slice,
273	  // lends up the direct parent chain, then the root pool. A single-gate
274	  // occupation gathers exactly the way a one-member combo would — its own
275	  // limit never caps the request, only the family pool does.
276	  function tryGatherOne(entry, g, units) {
277	    return tryGather(entry, buildSegs([g], () => units));
278	  }
279	
280	  // Release a held reservation wholesale. Pool room is refunded only while
281	  // the charged pool window is still the current one; a pool flip already
282	  // reclaimed it (the link is marked released and its gen is stale).
283	  function releaseHolds(entry) {
284	    if (!entry.holdsHeld || entry.segs === null) return;
285	    const r = entry.owner.root;
286	    for (const seg of entry.segs) {
287	      const m = seg.gate;
288	      if (!seg.ownReleased && seg.own > 0) {
289	        seg.ownReleased = true;
290	        m.pendingOwn -= seg.own;
291	        m.resvAsMember.delete(entry);
292	        if (seg.gen === r.poolGen) r.poolUsed -= seg.own;
293	      }
294	      for (const link of seg.links) {
295	        if (link.released) continue;
296	        link.released = true;
297	        if (link.kind === 'pool') {
298	          // delete() reports whether the link still charged the pool: a pool
299	          // flip already cleared the set and zeroed poolResvUnits, so a stale
300	          // link must not subtract twice.
301	          if (r.poolResv.delete(link)) r.poolResvUnits -= link.units;
302	          m.resvAsMember.delete(entry);
303	        } else {
304	          link.lender.pendingLends -= link.units;
305	          link.lender.resvAsLender.delete(entry);
306	        }
307	        if (link.gen === r.poolGen) r.poolUsed -= link.units;
308	      }
309	    }
310	    entry.holdsHeld = false;
311	    entry.segs = null;
312	  }
313	
314	  // --- Handles --------------------------------------------------------------
315	  //
316	  // The handle exposes exactly one own property, release, as a closure: the
317	  // destructured method called without a receiver works the same. Every link
318	  // remembers the generations of both sides, so a release after either window
319	  // flipped never subtracts quota that flip already settled.
320	
321	  function makeHandle(records) {
322	    let active = true;
323	    return {
324	      release() {
325	        if (!active) return;
326	        active = false;
327	        for (const rec of records) {
328	          const seg = rec.seg;
329	          const m = seg.member;
330	          const r = m.root;
331	          m.openHandles.delete(rec);
332	          if (seg.mgen === m.ownGen && seg.own > 0) {
333	            m.inFlight -= seg.own;
334	          }
335	          for (const link of seg.links) {
336	            const memberLive = seg.mgen === m.ownGen;
337	            const lenderLive =
338	              link.kind === 'pool' ? link.lgen === r.poolGen : link.lgen === link.lender.ownGen;
339	            if (!memberLive || !lenderLive) continue; // a window flip settled it
340	            m.inFlight -= link.units;
341	            m.borrowedInFlight -= link.units;
342	            if (link.kind === 'pool') {
343	              r.poolLinks.delete(link);
344	            } else {
345	              link.lender.lentLinks.delete(link);
346	              link.lender.inFlight -= link.units;
347	              link.lender.lentInFlight -= link.units;
348	            }
349	          }
350	        }
351	      },
352	    };
353	  }
354	
355	  // Commit a fully gathered combo: provisional promises become admitted
356	  // occupations. Pool room was charged at gather time, so poolUsed does not
357	  // move here.
358	  function commitCombo(entry) {
359	    const r = entry.owner.root;
360	    const records = [];
361	    const lenderCleanup = new Set();
362	    for (const seg0 of entry.segs) {
363	      const m = seg0.gate;
364	      const units = seg0.units;
365	      chargeDraw(m, units);
366	      let seg;
367	      if (m === r) {
368	        // The root member's whole slice is its own window and drew the pool
369	        // directly; consume its pool reservation link so it does not survive
370	        // the commit as uncommitted quota.
371	        for (const l0 of seg0.links) {
372	          if (l0.kind === 'pool' && r.poolResv.delete(l0)) r.poolResvUnits -= l0.units;
373	        }
374	        m.usedOwn += units;
375	        m.inFlight += units;
376	        m.resvAsMember.delete(entry);
377	        seg = { member: m, units, own: units, mgen: m.ownGen, links: [] };
378	      } else {
379	        const ownPart = seg0.own;
380	        m.usedOwn += ownPart;
381	        m.pendingOwn -= ownPart;
382	        m.resvAsMember.delete(entry);
383	        m.inFlight += units;
384	        const links = [];
385	        for (const l0 of seg0.links) {
386	          const link = {
387	            kind: l0.kind,
388	            lender: l0.lender,
389	            member: m,
390	            units: l0.units,
391	            lgen: l0.kind === 'pool' ? r.poolGen : l0.lender.ownGen,
392	            mgen: m.ownGen,
393	          };
394	          if (l0.kind === 'pool') {
395	            if (r.poolResv.delete(l0)) r.poolResvUnits -= l0.units;
396	            r.poolLinks.add(link);
397	          } else {
398	            const g = l0.lender;
399	            g.usedOwn += l0.units;
400	            g.pendingLends -= l0.units;
401	            lenderCleanup.add(g);
402	            g.inFlight += l0.units;
403	            g.lentInFlight += l0.units;
404	            link.pgen = r.poolGen; // pool window this lend charged
405	            g.lentLinks.add(link);
406	          }
407	          links.push(link);
408	        }
409	        m.borrowedInFlight += units - ownPart;
410	        seg = { member: m, units, own: ownPart, mgen: m.ownGen, links };
411	      }
412	      const rec = { seg };
413	      m.openHandles.add(rec);
414	      records.push(rec);
415	    }
416	    // One entry may borrow from the same ancestor for several sibling
417	    // members; drop its lender registration once, after every link settled.
418	    for (const g of lenderCleanup) g.resvAsLender.delete(entry);
419	    entry.holdsHeld = false;
420	    entry.segs = null;
421	    return makeHandle(records);
422	  }
423	
424	  // --- Queue entry lifecycle ------------------------------------------------
425	
426	  function detachSignal(entry) {
427	    if (entry.signal !== null) {
428	      entry.signal.removeEventListener('abort', entry.onAbort);
429	      entry.signal = null;
430	    }
431	  }
432	
433	  // One queue entry leaves the queue exactly once, and exactly one of
434	  // granted / refused / expired / cancelled moves as a result.
435	  function settleEntry(entry, outcome) {
436	    if (entry.removed) return;
437	    const ownerRoot = entry.owner.root;
438	    entry.removed = true;
439	    ownerRoot.liveQueued -= 1;
440	    clearTimeout(entry.timer);
441	    detachSignal(entry);
442	    for (const charge of entry.waitCharges) charge.gate.waiting -= charge.units;
443	    if (outcome === 'granted') {
444	      // Both singles and combos arrive here holding a gathered reservation;
445	      // the same commit turns provisional promises into the occupation.
446	      const handle = commitCombo(entry);
447	      entry.owner.granted += 1;
448	      entry.resolve(handle);
449	      return;
450	    }
451	    // Expiry, cancellation and refusal give back any hold; none of those
452	    // outcomes itself counts as a reservation rollback.
453	    releaseHolds(entry);
454	    if (outcome === 'refused') {
455	      entry.owner.refused += 1;
456	      entry.reject(new QuotaExceededError('QUOTA_EXCEEDED', 'quota exceeded'));
457	    } else if (outcome === 'cancelled') {
458	      entry.owner.cancelled += 1;
459	      entry.reject(
460	        new QuotaExceededError('CANCELLED', 'queued request was cancelled before quota was available'),
461	      );
462	    } else {
463	      entry.owner.expired += 1;
464	      entry.reject(
465	        new QuotaExceededError('WAIT_EXPIRED', 'queued request expired before quota was available'),
466	      );
467	    }
468	  }
469	
470	  // The wait timer measures real elapsed time, like the baseline. The
471	  // deadline field additionally gates window-flip sweeps when the monotonic
472	  // clock and the wall clock disagree (mocked/frozen clocks). Delays beyond
473	  // the 32-bit timer range fire in chunks so the cap is honoured in full
474	  // instead of overflowing to 1ms.
475	  function armEntry(entry, delay) {
476	    const chunk = Math.min(Math.max(1, delay), MAX_TIMER_DELAY);
477	    entry.timer = setTimeout(() => {
478	      if (entry.removed) return;
479	      const remaining = delay - chunk;
480	      if (remaining > 0) {
481	        armEntry(entry, remaining);
482	        return;
483	      }
484	      settleEntry(entry, 'expired');
485	    }, chunk);
486	    if (typeof entry.timer.unref === 'function') entry.timer.unref();
487	  }
488	
489	  // At the same moment expiry beats cancellation: an abort arriving once the
490	  // deadline has already passed settles as WAIT_EXPIRED.
491	  function onEntryAbort(entry) {
492	    if (entry.removed) return;
493	    if (entry.deadline <= now()) {
494	      settleEntry(entry, 'expired');
495	    } else {
496	      settleEntry(entry, 'cancelled');
497	    }
498	  }
499	
500	  function recomputeMinDeadline() {
501	    const r = state.root;
502	    let min = Infinity;
503	    const q = r.queue;
504	    for (let i = r.head; i < q.length; i += 1) {
505	      const entry = q[i];
506	      if (!entry.removed && entry.deadline < min) min = entry.deadline;
507	    }
508	    r.minDeadline = min;
509	  }
510	
511	  // Expiry is judged before quota allocation: anything due at or before the
512	  // flip moment expires rather than being granted.
513	  function sweepExpired(t) {
514	    const r = state.root;
515	    if (r.minDeadline > t) return;
516	    let min = Infinity;
517	    for (let i = r.head; i < r.queue.length; i += 1) {
518	      const entry = r.queue[i];
519	      if (entry.removed) continue;
520	      if (entry.deadline <= t) settleEntry(entry, 'expired');
521	      else if (entry.deadline < min) min = entry.deadline;
522	    }
523	    r.minDeadline = min;
524	  }
525	
526	  // Allocation walks arrivals in order against the freshly reset pool. A head
527	  // combo that cannot be gathered whole does not starve later arrivals: a
528	  // later request that fits outright passes it and the combo yields once;
529	  // after yielding twice (cumulatively, across flips) it becomes a hard
530	  // barrier like a non-fitting single. The pass is O(1) per live queue entry:
531	  // a single monotonic counter (serveWave, bumped once per overtaking serve)
532	  // lets each blocked combo derive its yield count without being touched by
533	  // the requests that pass it.
534	  function allocate() {
535	    const r = state.root;
536	    const q = r.queue;
537	    let wave = r.serveWave; // overtakes counted so far, monotonic across passes
538	    let stopWave = Infinity; // earliest wave at which a blocker hardens
539	    let blockerCount = 0; // blocked combos registered earlier in this/prev passes
540	    for (let i = r.head; i < q.length; i += 1) {
541	      const entry = q[i];
542	      if (entry.removed) continue;
543	      if (wave >= stopWave) break;
544	      let served = false;
545	      if (!entry.combo) {
546	        // The pool flip (or a member/ancestor flip) may have reclaimed part
547	        // of the held reservation; release what survived and gather anew.
548	        if (entry.holdsHeld) releaseHolds(entry);
549	        if (tryGatherOne(entry, entry.owner, entry.units)) {
550	          settleEntry(entry, 'granted');
551	          served = true;
552	        } else {
553	          // A single request cannot overtake and is not overtaken: it is an
554	          // ordinary hard barrier against later arrivals, exactly like the
555	          // baseline. No rollback counter moves for a single-gate attempt.
556	          break;
557	        }
558	      } else {
559	        // Combo's turn against the fresh pool: the pool flip reclaimed its
560	        // pool side; release the surviving own-side holds and gather anew.
561	        if (entry.holdsHeld) releaseHolds(entry);
562	        const segs = buildSegs(entry.comboGates, (g) => entry.comboUnits.get(g));
563	        if (tryGather(entry, segs)) {
564	          settleEntry(entry, 'granted');
565	          served = true;
566	        } else {
567	          // Any step short: the plan touched nothing; count one whole
568	          // rollback (no other counter moves) and register a soft barrier.
569	          entry.owner.rolledBack += 1;
570	          if (entry.blockG !== -1) entry.yields += wave - entry.blockG;
571	          entry.blockG = wave;
572	          const hardensAt = wave + (2 - entry.yields);
573	          blockerCount += 1;
574	          if (hardensAt < stopWave) stopWave = hardensAt;
575	        }
576	      }
577	      if (served && blockerCount > 0) wave += 1; // one yield per overtaken blocker
578	    }
579	    r.serveWave = wave;
580	    while (r.head < q.length && q[r.head].removed) r.head += 1;
