  await assert.rejects(p, (err) => {
    assert.ok(err instanceof QuotaExceededError);
    assert.equal(err.code, 'CANCELLED');
    return true;
  });
  const s = gate.stats();
  assert.equal(s.cancelled, 1);
  assert.equal(s.waiting, 0);
  assert.equal(s.granted, 1);
  assert.equal(s.refused, 0);
